import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(0)
        return

    n = int(data[0])

    if n == 0:
        print(0)
        return

    matrix = []
    index = 1
    for i in range(n):
        row = list(map(int, data[index:index + n]))
        matrix.append(row)
        index += n

    prime_digits = {2, 3, 5, 7}
    total = 0

    for i in range(n):
        primary_digit = matrix[i][i]
        secondary_digit = matrix[i][n - 1 - i]

        if i == n - 1 - i:
            if primary_digit in prime_digits:
                total += primary_digit
        else:
            if primary_digit in prime_digits:
                total += primary_digit
            if secondary_digit in prime_digits:
                total += secondary_digit

    print(total)

if __name__ == "__main__":
    main()
